WoWBY_SpellDescRU = {}
;(function() local SDR = WoWBY_SpellDescRU
SDR["0005835d"]={"^Мгновенно наносит (.-)%% урона от оружия и еще (.-) ед%. урона от светлой магии%.$",{"Імгненны ўдар, які наносіць ",1,"% урону ад зброі плюс дадаткова ",2," урону ад светлай магіі."}}
SDR["000863c3"]={"^Усиление роя%. Урон и объем исцеления от заклинаний увеличены максимум на (.-) ед%. Сила атаки повышена на (.-)%.$",{"Узмоцнены Роем. Наносіць да ",1," дадатковага ўрону і лячэння заклёнамі, а сіла атакі павялічана на ",2,"."}}
SDR["000eb517"]={"^Заряжено%. Следующий противник, нанесший вам удар в ближнем бою, будет обезоружен%.$",{"Зараджаны; наступны нападнік у блізкім баі, які ўдарыць вас, будзе абяззброены."}}
SDR["0012a0f0"]={"^Использовать в Гробнице Семерых в Глубинах Черной Скалы%.$",{"Выкарыстаць у Грабніцы Семярых у Глыбінях Чорнай гары."}}
SDR["0019f737"]={"^Повышение наносимого урона от заклинаний не более чем на 120 ед%. и исцеляющих эффектов на величину вплоть до 300 ед%.$",{"Павялічвае ваш урон ад заклёнаў максімум на 120, а ваша лячэнне — максімум на 300."}}
SDR["001d12e2"]={"^Получает на (.-)%% больше урона от эффекта \"(.-)\"%.$",{"Атрыманы ўрон ад ",2," павялічаны на ",1,"%."}}
SDR["0022b069"]={"^Улучшает ваши яды несколькими эффектами:\n\nПоражая цель любым другим ядом, вы также отравляете ее \"Смертельным ядом\"%.\n\nЕсли на вашем оружии нет яда, оно может поразить цель \"Быстродействующим ядом\", словно он был нанесен на оружие%.\n\nУрон от \"Смертельного яда\" и \"Быстродействующего яда\" теперь увеличивается в зависимости от вашей силы атаки%.\n\nВаш \"Смертельный яд\" теперь может действовать на цели одновременно со \"Смертельным ядом\" другого разбойника%.$",{"Дае некалькі паляпшэнняў вашым атрутам:\n\nКалі вы накладаеце на цэль любую іншую атруту, вы таксама накладаеце «Смяротную атруту».\n\nКалі на вашу зброю не нанесена атрута, яна мае шанец выклікаць дзеянне «Імгненнай атруты», быццам «Імгненная атрута» была нанесена.\n\n«Смяротная атрута» і «Імгненная атрута» цяпер атрымліваюць павялічаны ўрон ад вашай сілы атакі.\n\nВаша «Смяротная атрута» цяпер можа дзейнічаць на цэлях, на якіх ужо дзейнічае «Смяротная атрута» іншага гульца."}}
SDR["002aaa28"]={"^Наносит (.-) ед%. урона от сил природы цели и ближайшему противнику рядом с ней%. Растительные существа и нежить получают в (.-) (.-) больше урона%.$",{"Наносіць цэлі і яе найбліжэйшаму саюзніку ",1," урону ад сіл прыроды. Наносіць у ",2," разы больш урону раслінам і нежыці."}}
SDR["002befd8"]={"^Повышает скорость атаки и применения заклинаний на (.-)%%%. Увеличивает получаемый урон от сил природы на (.-)%%%.$",{"Павялічвае хуткасць атакі і прымянення заклёнаў на ",1,"%. Павялічвае атрыманы ўрон ад сіл прыроды на ",2,"%."}}
SDR["00315918"]={"^Урон и сила исцеления увеличены на (.-)%%%. Эффект усиливается рядом с находящимися рядом игроками с положительным зарядом%.\n\nНаносит (.-) ед%. урона находящимся рядом союзникам без положительного заряда раз в (.-) сек%.$",{"Нанесены ўрон і выкананае лячэнне павялічаны на ",1,"%. Гэты эфект узмацняецца ад блізкіх станоўча зараджаных саюзнікаў.\n\nНаносіць ",2," урону блізкім саюзнікам, якія не маюць станоўчага зараду, кожныя ",3," сек."}}
SDR["0036f9c9"]={"^Выпейте, чтобы улучшить ориентацию в пространстве, что позволит вам в течение (.-)%. видеть скрытые травы и месторождения руды%.\n\nЭффект сохраняется после смерти%.$",{"Выпіць, каб палепшыць прасторавае ўспрыманне, што дазваляе бачыць схаваныя радовішчы руды і травы на ",1,".\n\nГэты эфект захоўваецца пасля смерці."}}
SDR["0045a5fb"]={"^Выгравировать на наручах руну \"Обжигающий жар\":\n\n(.-)\n(.-)$",{"Выгравіраваць на наручах руну «Аўра спальвання»:\n\n",1,"\n",2}}
SDR["0046ffef"]={"^Окружает цель щитом огня, который наносит (.-) ед%. урона от огня атакующим противникам%. Время действия – (.-)%. Прислужник не может применить \"Огненный щит\" к себе%.$",{"Атачае цэль шчытом агню. Кожны ўдар па цэлі наносіць нападніку ",1," урону ад агню. Дзейнічае ",2,". Ваш гадаванец не можа ўжыць «Вогненны шчыт» на самога сябе."}}
SDR["004a4909"]={"^\"Дубовую кожу\" теперь можно применять к союзникам и в любом облике%. Она больше не замедляет скорость атаки в ближнем бою и скорость применения заклинаний%.$",{"Вашу «Дубовую скуру» цяпер можна ўжываць на саюзнікаў, яна больш не зніжае хуткасць атак у блізкім баі і час прымянення заклёнаў, а таксама яе можна ўжываць у любым абліччы."}}
SDR["00565e8e"]={"^Оглушает вас и восполняет (.-) ед%. здоровья за (.-)%. В лесах и полях повышает выносливость на (.-) на (.-)%.$",{"Аглушае вас і аднаўляе ",1," здароўя за ",2,". У лясных і лугавых зонах дае ",3," целабудовы на ",4,"."}}
SDR["005784d8"]={"^Искажает пространство%-время, временно отключая полезные глобальные эффекты клича Драконоборца, Зул'Гуруба, Забытого Города и Оскверненного леса%.$",{"Змяняе тканіну часу, прыпыняючы дзеянне карысных сусветных эфектаў ад забойства драконаў, Жудаснага Молата, Зул'Гуруба і Апаганенага лесу."}}
SDR["00579042"]={"^Наносимый демонам урон увеличен на (.-)%%%.$",{"Павялічвае ўрон, які наносіцца дэманам, на ",1,"%."}}
SDR["00621e70"]={"^Дает вам и призванному демону эффект, действующий, пока жив демон%.\n\nБес: увеличивает наносимый урон от огня на (.-)%%%.\n\nДемон Бездны: уменьшает получаемый физический урон на (.-)%%%.\n\nСуккуб/инкуб: увеличивает наносимый урон от темной магии на (.-)%%%.\n\nОхотник Скверны: уменьшает получаемый магический урон на (.-)%%%.$",{"Дае чарнакніжніку і закліканаму дэману эфект, пакуль гэты дэман актыўны.\n\nБіс — павялічвае нанесены ўрон ад агню на ",1,"%.\n\nПустотнік — зніжае атрыманы фізічны ўрон на ",2,"%.\n\nСукуба / інкуб — павялічвае нанесены ўрон ад цёмнай магіі на ",3,"%.\n\nПаляўнічы Скверны — зніжае атрыманы магічны ўрон на ",4,"%."}}
SDR["00650370"]={"^Повышает все виды сопротивления на (.-)%. Бонус увеличивается еще на (.-) в лесах и полях%.$",{"Павялічвае ўсе супраціўленні на ",1,". Усе супраціўленні дадаткова павялічваюцца на ",2," у лясах і на лугах."}}
SDR["006aa93c"]={"^Свинобразы из укрытия Дыбогривов временно терпят ваше присутствие%.$",{"Ігладзікі з Прытулку Шчацінаспінаў пакуль што цярпяць вашу прысутнасць."}}
SDR["006ccc41"]={"^Похищает у цели (.-) ед%. здоровья раз 1 сек%. Время действия – (.-)%.$",{"Перадае ",1," здароўя кожную секунду ад цэлі да заклінальніка. Дзейнічае ",2,"."}}
SDR["006dda07"]={"^Интеллект повышен на (.-)%.$",{"Ваш інтэлект павялічаны на ",1,"."}}
SDR["006e47c4"]={"^Скорость атаки повышена на (.-)%%%. Наносимый урон увеличен на (.-)%%%.$",{"Хуткасць атакі павялічана на ",1,"%. Урон павялічаны на ",2,"%."}}
SDR["006ff60e"]={"^При применении к выбранному оружию восполняет 12 ед%. маны за 5 сек%. и повышает меткость заклинаний на 2%% на (.-) мин%. Этот эффект действует только в Непроглядной Пучине%.\n$",{"Пры нанясенні на выбраную зброю аднаўляе 12 маны кожныя 5 сек. і павялічвае верагоднасць трапляння заклёнамі на 2% на ",1," хв. Гэты эфект дзейнічае толькі ў Чорных Глыбінях.\n"}}
SDR["00750eb1"]={"^Увеличение силы на (.-) ед%. и получение (.-) ед%. урона раз в (.-) сек%. В течение (.-)%.$",{"Павялічвае сілу на ",1," і наносіць вам ",2," урону кожныя ",3," сек. на ",4,"."}}
SDR["007592d2"]={"^Невосприимчивость к болезням%.$",{"Імунітэт да хвароб."}}
SDR["0078c384"]={"^Оглушение%. Получаемый урон от огня увеличен на (.-)%%%.$",{"Аглушаны. Атрыманы ўрон ад агню павялічаны на ",1,"%."}}
SDR["007a277d"]={"^Вероятность критического эффекта заклинаний повышается на (.-)%%%. Урон и объем исцеления от заклинаний увеличиваются на (.-) ед%. Скорость атаки в ближнем и дальнем бою повышается на (.-)%%%. Время действия – 120 мин%.\n$",{"Павялічвае шанец крытычнага ўдару заклёнаў на ",1,"%, дае да ",2," да ўрону і лячэння ад заклёнаў і павялічвае хуткасць атакі ў блізкім і дальнім баі на ",3,"%. Дзейнічае 120 хв.\n"}}
SDR["007a7b5e"]={"^Навсегда усилить наплечники душой демонического экзорциста:\n\n(.-)$",{"Назаўжды надзяліць наплечнікі душой дэманічнага экзарцыста:\n\n",1}}
