SDR["414d5ff0"]={"^Дает способность \"Всплеск крови\":\n\n(.-)\n(.-)$",{"Дае здольнасць «Усплёск крыві»:\n\n",1,"\n",2}}
SDR["4154fe84"]={"^Максимальный запас здоровья увеличен на (.-) ед%. Броня усилена на (.-) ед%.$",{"Максімальны запас здароўя павялічаны на ",1,", а браня — на ",2,"."}}
SDR["41590328"]={"^Если цель парирует, блокирует ваше \"Сокрушение щитом\" или уклоняется от него, создаваемый им уровень угрозы повышается на (.-)%%, а его время восстановления обновляется%.$",{"Ваш «Магутны ўдар шчытом» стварае на ",1,"% больш пагрозы, а яго час аднаўлення скідаецца, калі ад яго ўхіліліся, яго парыравалі або заблакавалі."}}
SDR["4175b8b9"]={"^Время восстановления \"Прилива сил\" сокращается на (.-)%%%.$",{"Скарачае час аднаўлення вашай здольнасці «Прыліў сіл» на ",1,"%."}}
SDR["417a1dfe"]={"^Значительное усиление обнаружения незаметности и отображение на мини%-карте всех незаметных объектов в радиусе действия%. Одновременно можно использовать только одну форму слежения%.$",{"Павялічвае выяўленне схаванасці і паказвае схаваных істот у радыусе выяўлення на міні-карце. Адначасова можа быць актыўны толькі адзін від высочвання."}}
SDR["417db7ef"]={"^Нанесение (.-) ед%. урона от тайной магии любому существу, атакующему находящегося рядом приспешника%.$",{"Наносіць ",1," урону ад арканы любой істоце, якая атакуе прыспешніка паблізу."}}
SDR["4184607c"]={"^Возможность понимать основной язык противоположной фракции%.$",{"Дазваляе разумець асноўную мову супрацьлеглай фракцыі."}}
SDR["418c3466"]={"^На голове чего%-то не хватает%.%.%.$",{"Здаецца, на яго галаве чагосьці не хапае..."}}
