SDR["48f43ed4"]={"^Повышает силу атаки дальнего боя участников группы или рейда в радиусе (.-) м на (.-)%.$",{"Павялічвае сілу дальняй атакі членаў групы або рэйду ў радыусе ",1," м на ",2,"."}}
SDR["48f85a7b"]={"^Увеличение скорости атаки на (.-)%%%.\nУве урона на (.-)%%%.$",{"Хуткасць атакі павялічана на ",1,"%.\nУрон павялічаны на ",2,"%."}}
